using System.Collections;
using Astrea.BattleActions;
using LittleLeo;
using LittleLeo.Events;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "OutbreakEffect", menuName = "Data/Battle/Effects/Enemy/Outbreak Effect")]
public class OutbreakEffect : Effect
{
	[Header("Outbreak Effect")]
	[SerializeField]
	private DefaultEffectAction doomAction;

	[SerializeField]
	private float delayToDoom;

	[SerializeField]
	private Effect protectionEffect;

	[Header("Screen Shake")]
	[SerializeField]
	private FloatFloatEvent OnScreenShake;

	[SerializeField]
	private float screenShakeDuration;

	[SerializeField]
	private float screenShakePower;

	[Header("Enemy Shake")]
	[SerializeField]
	private float enemyShakeDuration;

	[SerializeField]
	private float enemyShakePower;

	protected override string GetEffectDescriptionWithAmountReplacedWithX(string localizedDescription, int amount, GameObject effectOwner)
	{
		localizedDescription = localizedDescription.Replace(" ({0}) ", "").Replace(" ({0})", "").Replace("（{0}）", "");
		localizedDescription = localizedDescription.Replace("{1}", "{0}");
		localizedDescription = Smart.Format(localizedDescription, base.localizationManager.GetLocalizedEnemyEffectOwnerReceiveEffectFormatted(doomAction.Effect, amount));
		return localizedDescription;
	}

	protected override string GetEffectDescriptionWithAmount(int amount, GameObject effectOwner)
	{
		int num = 0;
		if (effectOwner != null && GameScenesUtils.IsBattleScene() && (bool)effectOwner.GetComponent<CorruptionStats>())
		{
			CorruptionStats component = effectOwner.GetComponent<CorruptionStats>();
			num = GetEffectOwnerHalfMaxCorruption(component);
		}
		return Smart.Format(GetLocalizedDescription(), num, base.localizationManager.GetLocalizedEnemyEffectOwnerReceiveEffectFormatted(doomAction.Effect, amount));
	}

	public override int ActivateEffect(int amount, GameObject effectOwner)
	{
		CorruptionStats component = effectOwner.GetComponent<CorruptionStats>();
		if (component.CurrentCorruption <= (float)GetEffectOwnerHalfMaxCorruption(component))
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(ApplyEmpower(effectOwner, amount));
			ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
		}
		else if (component.CurrentCorruption <= (float)Mathf.FloorToInt(component.MaxCorruption / 3f * 2f))
		{
			effectOwner.GetComponent<UnitEffects>().IsEffectActiveGetEffectInstance(this).PlayBlinkingFeedback();
		}
		return amount;
	}

	private int GetEffectOwnerHalfMaxCorruption(CorruptionStats corruptionStats)
	{
		return Mathf.FloorToInt(corruptionStats.MaxCorruption / 2f);
	}

	private IEnumerator ApplyEmpower(GameObject effectOwner, int amount)
	{
		UnitEffects unitEffects = effectOwner.GetComponent<UnitEffects>();
		if (!unitEffects.IsEffectActive(this, activateFeedback: false))
		{
			yield break;
		}
		yield return new WaitForSeconds(0.2f);
		if (effectOwner.GetComponent<CorruptionStats>().IsDefeated())
		{
			yield break;
		}
		unitEffects.IsEffectActive(this);
		if (IsVFXEnabled())
		{
			PlayEffectActivationSFX();
			GameObject vFX = GetVFX(GetVFXOwnerPosition(effectOwner));
			ReferenceSingleton<VFXHandler>.Instance.AddToVFXHolders(new VFXHolder(effectOwner, this, vFX));
			vFX.GetComponent<ParticleEmissionController>().SetActive(value: true);
			OnScreenShake.Raise(screenShakePower, screenShakeDuration);
			CoroutineUtility.ShakeRoutine(ReferenceSingleton<CoroutineHandler>.Instance, effectOwner.GetComponent<SpriteControl>().SkeletonTransform, enemyShakeDuration, enemyShakePower);
			yield return new WaitForSeconds(delayToDoom);
		}
		else
		{
			yield return new WaitForSeconds(0.4f);
		}
		if (unitEffects.IsEffectActive(protectionEffect, activateFeedback: false))
		{
			VFXHolder vFXInstanceFromVFXHoldersAndRemoveItFromList = ReferenceSingleton<VFXHandler>.Instance.GetVFXInstanceFromVFXHoldersAndRemoveItFromList(effectOwner, this);
			if (vFXInstanceFromVFXHoldersAndRemoveItFromList != null)
			{
				GameObject vFXInstance = vFXInstanceFromVFXHoldersAndRemoveItFromList.VFXInstance;
				vFXInstance.GetComponent<ParticleEmissionController>().SetActive(value: false);
				ReferenceSingleton<PoolHandler>.Instance.StoreObject(vFXInstance, 2f);
			}
		}
		doomAction.CastTargetAmount(effectOwner, amount, null);
		unitEffects.RemoveEffect(this, activateFeedback: false);
		yield return new WaitForSeconds(0.2f);
	}
}
